<script setup lang="ts">
import { onUnmounted,ref } from 'vue';
import { Http,ApiError } from '../api/http';
import { SerialRead } from '../realtime/serial';
import { decode } from '../api/json';
import { date,stateName,errorText,type Monitoring } from './model';
import MonitoringPanel from './MonitoringPanel.vue';
import './business.css';
const http=new Http(),no=ref(''),code=ref(''),error=ref(''),data=ref<Monitoring|null>(null),busy=ref(false);let token='',reader:SerialRead|undefined,timer:ReturnType<typeof setInterval>|undefined,expiry:ReturnType<typeof setTimeout>|undefined,generation=0;
function clear(message=''){generation++;token='';reader?.stop();clearInterval(timer);clearTimeout(expiry);data.value=null;code.value='';busy.value=false;error.value=message;}
async function view(signal:AbortSignal,epoch:number){try{const response=await fetch('/api/v1/public/transport-view',{signal,headers:{'X-Transport-View-Token':token},credentials:'omit'});const body=decode<{data:Monitoring;request_id:string;error?:{code:string}}>(await response.text());if(!response.ok)throw new ApiError(response.status,body.request_id,body.error?.code);if(epoch===generation&&!signal.aborted){data.value=body.data;error.value='';}}catch(e){if(signal.aborted||epoch!==generation)return;if(e instanceof ApiError&&[401,403].includes(e.status))clear(errorText(e));else error.value=errorText(e);}}
async function verify(){if(busy.value||token)return;const epoch=++generation;busy.value=true;error.value='';try{const result=await http.request<{token:string;expires_at:number}>('/public/transport-access/verify',{method:'POST',body:{transport_no:no.value.trim(),code:code.value},login:true});if(epoch!==generation)return;code.value='';token=result.token;reader=new SerialRead(signal=>view(signal,epoch),200);reader.trigger();timer=setInterval(()=>reader?.trigger(),10000);expiry=setTimeout(()=>clear('查看会话已到期，请重新验证'),Math.max(0,result.expires_at-Date.now()));}catch(e){if(epoch===generation)error.value=errorText(e);}finally{if(epoch===generation)busy.value=false;}}
onUnmounted(()=>clear());
</script>
<template><div class="track-shell"><header class="track-header"><span class="business-brand"><span>S</span>SmartBox</span><span>运输查看</span></header><main class="track-content"><p v-if="error" class="biz-error" role="alert">{{ error }}</p><template v-if="!data"><section class="track-intro"><div class="parcel-symbol" aria-hidden="true">▱</div><h1>查看这一程。</h1><p>输入骑手提供的运输编号和验证码，查看本次运输状态。</p></section><form class="track-form" @submit.prevent="verify"><label for="transport-number">运输编号</label><input id="transport-number" v-model="no" required maxlength="64" autocomplete="off" placeholder="TR-…"><label for="view-code">查看验证码</label><input id="view-code" v-model="code" required maxlength="64" autocomplete="off"><button class="biz-primary" :disabled="busy">{{ busy?'正在验证…':'验证并查看' }}</button></form><p class="biz-note">无需注册账号。凭据只用于本次运输，刷新页面后需要重新验证。</p></template><template v-else><div class="page-heading"><div><p class="biz-muted">{{ data.task.transport_no }}</p><h1>{{ data.task.item_name }}</h1><p>{{ data.task.item_description }}</p></div><span :class="['task-state',data.task.status]">{{ stateName(data.task.status) }}</span></div><div class="transport-times"><span>开始 {{ date(data.task.started_at) }}</span><span>结束 {{ date(data.task.ended_at) }}</span></div><MonitoringPanel :data="data"/><div class="track-actions"><button class="biz-secondary" @click="reader?.trigger()">刷新</button><button class="biz-text" @click="clear()">退出查看</button></div></template></main><footer class="business-footer">只展示本次运输可确认的数据。定位与完整补传不在本页展示范围。</footer></div></template>
